    boiler: "mdi:water-boiler",
    ahu: "mdi:air-filter",
    room: "mdi:home-thermometer-outline",
    meter: "mdi:gauge",
    solar: "mdi:solar-panel-large",
    pv: "mdi:solar-power-variant",
    grid: "mdi:transmission-tower",
    generic: "mdi:cube-outline",
